package com.cyclecare.core.domain.prediction

import com.cyclecare.core.model.CycleSource
import com.google.common.truth.Truth.assertThat
import java.io.File
import java.time.LocalDate
import org.junit.Test

/**
 * The golden fixtures of spec `12` §7.
 *
 * A fixture is a full input and the exact output the engine produced for
 * it, pinned per algorithm version. It is the regression defence: a
 * behaviour change that nobody intended shows up here as a diff, and
 * `12` §7 rule 2 says a diff without a version bump is a defect rather
 * than an update.
 *
 * The fixtures are generated by [GoldenFixtures.generate] and reviewed
 * before they are committed. Nothing regenerates them automatically: a
 * fixture that a test rewrote would stop testing anything.
 */
class PredictionGoldenFixtureTest {

    private val engine = CyclePredictionEngineV2()

    @Test
    fun everyFixtureTheSpecificationNamesIsCommitted() {
        val named = listOf(
            "stable_28_8cycles.json",
            "regular_28_sigma2_6cycles.json",
            "single_200day_outlier.json",
            "impossible_gap_excluded.json",
            "insufficient_history_2cycles.json",
            "drifting_up.json",
            "corrected_retroactive_edit.json",
            "leap_year_boundary.json",
        )

        val present = fixtureDirectory().listFiles()?.map { it.name }?.sorted().orEmpty()
        assertThat(present).containsExactlyElementsIn(named)
    }

    @Test
    fun everyFixtureReproducesExactly() {
        val files = fixtureDirectory().listFiles()?.sortedBy { it.name }.orEmpty()
        assertThat(files).isNotEmpty()

        files.forEach { file ->
            val fixture = GoldenFixtures.read(file)

            // `12` §7 rule 2: a behaviour change requires a version bump.
            // A fixture generated under another version is a defect, not
            // an update, so the version has to match the code.
            assertThat(fixture["algorithmVersion"].toString())
                .isEqualTo(PREDICTION_ALGORITHM_VERSION)

            val observed = (fixture["observed"] as List<*>).map { entry ->
                val record = entry as Map<*, *>
                ObservedCycleStart(
                    id = record["id"].toString(),
                    startDate = LocalDate.parse(record["startDate"].toString()),
                    endDate = (record["endDate"] as String?)?.let { LocalDate.parse(it) },
                    source = CycleSource.valueOf(record["source"].toString()),
                )
            }
            val today = LocalDate.parse(fixture["today"].toString())

            val prediction = requireNotNull(
                engine.predict(
                    CyclePredictionInput(
                        observed = observed,
                        userReportedAverageCycleLength = null,
                        today = today,
                    ),
                ),
            ) { "the engine produced no prediction for ${file.name}" }

            val expected = fixture["expected"] as Map<*, *>

            assertThat(prediction.nextPeriodDate.toString())
                .isEqualTo(expected["nextPeriodDate"].toString())
            assertThat(prediction.ovulationDate.toString())
                .isEqualTo(expected["ovulationDate"].toString())
            assertThat(prediction.centerCycleLength)
                .isWithin(1e-9).of((expected["centerCycleLength"] as Number).toDouble())
            assertThat(prediction.dispersionSigma)
                .isWithin(1e-9).of((expected["dispersionSigma"] as Number).toDouble())
            assertThat(prediction.trendAdjustmentDays)
                .isWithin(1e-9).of((expected["trendAdjustmentDays"] as Number).toDouble())
            assertThat(prediction.isIrregular).isEqualTo(expected["isIrregular"])
            assertThat(prediction.isStale).isEqualTo(expected["isStale"])
            assertThat(prediction.quality.name).isEqualTo(expected["quality"].toString())
            assertThat(prediction.warnings.map { it.name })
                .containsExactlyElementsIn((expected["warnings"] as List<*>).map { it.toString() })
                .inOrder()
            assertThat(prediction.recordIdsUsed)
                .containsExactlyElementsIn((expected["recordIdsUsed"] as List<*>).map { it.toString() })
                .inOrder()

            assertWindow(prediction.nextPeriodWindow, expected["nextPeriodWindow"], file.name, "nextPeriodWindow")
            assertWindow(prediction.fertileWindow, expected["fertileWindow"], file.name, "fertileWindow")
            assertIntervals(prediction.intervalsUsed, expected["intervalsUsed"], file.name, "intervalsUsed")
            assertIntervals(prediction.intervalsExcluded, expected["intervalsExcluded"], file.name, "intervalsExcluded")
        }
    }

    @Test
    fun theFertileWindowInEveryFixtureIsTheSpecifiedShape() {
        // The version bump that came with `2.1.0` is only meaningful if
        // the fertile window really is the shape spec `11` §4.5
        // describes: the population-typical window, widened by the
        // estimate's uncertainty and by the irreducible luteal floor.
        val files = fixtureDirectory().listFiles()?.sortedBy { it.name }.orEmpty()

        files.forEach { file ->
            val fixture = GoldenFixtures.read(file)
            val expected = fixture["expected"] as Map<*, *>
            val window = expected["fertileWindow"] as Map<*, *>?
            if (window == null) return@forEach

            val ovulation = LocalDate.parse(expected["ovulationDate"].toString())
            val before = java.time.temporal.ChronoUnit.DAYS.between(
                LocalDate.parse(window["start"].toString()),
                ovulation,
            ).toInt()
            val after = java.time.temporal.ChronoUnit.DAYS.between(
                ovulation,
                LocalDate.parse(window["endInclusive"].toString()),
            ).toInt()

            assertThat(before).isGreaterThan(after)
            assertThat(before - after)
                .isEqualTo(FERTILE_WINDOW_DAYS_BEFORE_OVULATION - FERTILE_WINDOW_DAYS_AFTER_OVULATION)
        }
    }

    @Test
    fun theCommittedFixturesAreExactlyWhatTheGeneratorProduces() {
        // Spec `12` §7 rule 1: the fixtures are generated, then reviewed
        // and committed. This regenerates them into a scratch directory
        // and compares, so a fixture that was hand-edited fails rather
        // than sitting there looking authoritative. The committed files
        // are never written by a test.
        val scratch = File("build/golden-fixtures")
        scratch.deleteRecursively()
        val generated = GoldenFixtures.generate(scratch)

        val committed = fixtureDirectory()
        assertThat(generated).hasSize(committed.listFiles()?.size ?: 0)

        generated.forEach { file ->
            val committedFile = File(committed, file.name)
            assertThat(committedFile.exists()).isTrue()
            assertThat(file.readText()).isEqualTo(committedFile.readText())
        }
    }

    private fun assertWindow(
        actual: DateWindow?,
        expected: Any?,
        fileName: String,
        field: String,
    ) {
        if (expected == null) {
            assertThat(actual).isNull()
            return
        }
        assertThat(actual).isNotNull()
        val window = requireNotNull(actual)
        val fixture = expected as Map<*, *>
        assertThat(window.start.toString()).isEqualTo(fixture["start"].toString())
        assertThat(window.endInclusive.toString()).isEqualTo(fixture["endInclusive"].toString())
        assertThat(window.halfWidthDays).isEqualTo((fixture["halfWidthDays"] as Number).toInt())
        assertThat(fileName).isNotEmpty()
    }

    private fun assertIntervals(
        actual: List<IntervalEstimate>,
        expected: Any?,
        fileName: String,
        field: String,
    ) {
        val fixtureIntervals = expected as List<*>
        assertThat(actual).hasSize(fixtureIntervals.size)
        actual.forEachIndexed { index, interval ->
            val fixture = fixtureIntervals[index] as Map<*, *>
            assertThat(interval.fromRecordId).isEqualTo(fixture["fromRecordId"].toString())
            assertThat(interval.toRecordId).isEqualTo(fixture["toRecordId"].toString())
            assertThat(interval.startDate.toString()).isEqualTo(fixture["startDate"].toString())
            assertThat(interval.lengthDays).isEqualTo((fixture["lengthDays"] as Number).toInt())
            assertThat(interval.usable).isEqualTo(fixture["usable"])
            assertThat(interval.exclusionReason).isEqualTo(fixture["exclusionReason"] as String?)
        }
        assertThat(fileName).isNotEmpty()
        assertThat(field).isNotEmpty()
    }

    /** The committed fixture directory. */
    private fun fixtureDirectory(): File {
        val candidates = listOf(
            File("src/test/resources/${GoldenFixtures.DIRECTORY}"),
            File("../core/domain/src/test/resources/${GoldenFixtures.DIRECTORY}"),
        )
        return candidates.firstOrNull { it.isDirectory }
            ?: throw AssertionError(
                "Could not find the golden fixtures. Looked in " + candidates.joinToString(", ") { it.absolutePath },
            )
    }
}
